"""Derive SkyyTrees/build_skyytrees_0.6.4.py from SkyyTrees 0.6.3 (build_skyytrees_0.6.3.py = the SET pin, itself GENERATED by
tools/trees_0_6_3_patch.py). Edit THIS patch, never the generated script. Every anchor is asserted once; at the end every change is undone on
a copy and compared with 0.6.3 (tools/soundpass_gen.Patch).
Run:
    python tools/art/make_r064_icons.py --check && python tools/classes_0_1_50_patch.py && python SkyyClasses/build_skyyclasses_0.1.50.py
    python tools/trees_0_6_4_patch.py && python SkyyTrees/build_skyytrees_0.6.4.py && python SkyyTrees/test_skyytrees_0.6.4.py
The class tree layout lives in tools/trees_v3_data.py r064_apply() (opt-in: only this build calls it, IN PLACE OF r063_apply - it runs
r063_apply itself between its two steps; every other build reads the table unchanged). Pairs with SkyyClasses 0.1.50 (Shadow Mark + the 8
new capstone codes; tools/classes_0_1_50_patch.py). The build cross-checks C_ABILS against the newest SkyyClasses build script it finds
(0.1.50: + Shadow Mark) - build SkyyClasses 0.1.50's script first.
"""
import os, sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, os.path.join(ROOT, "tools"))
import soundpass_gen as G

NOTE = '''0.6.4 (2026-10-24) = A CAPSTONE AT THE END OF EVERY A1-ALT PATH + THE ASSASSIN'S SECOND A1-ALT (with SkyyClasses 0.1.50).
  Skyy (docs/answered/classes.md 2026-10-24 PER-PATH CAPSTONES + 2ND ASSASSIN ALT, after the question "four branch-1 capstones belong to one
  alt path ... give each path its own capstone? [yes]; the Assassin has only one A1 alt - add a second? [yes]"): "Start the next queued
  rounds from RESUME (Islands retry, per-path capstones + 2nd Assassin alt, HUD Farming line, R5 Combat shard islands)."
  1. PER-PATH CAPSTONES (tools/trees_v3_data.py r064_apply, R064_CAPS / R064_PROMOTE): row 6 of branch 1 holds a capstone for EACH A1-alt
     path (+ the trunk capstone of the classes that had one: Untouchable, Ghost Protocol, Cataclysm, Miracle - both paths reach it):
       kept      Aegis Eternal (Warrior A), Crimson Eternal (Berserker A), Riftmaw (Spellblade A), Spider's Den (Archer B)
       moved up  from row 5 into row 6 (keys, ranks, effects unchanged): Warlord's Domain (Berserker B), No Mind (Monk B), Prism Overload
                 (Mage B), Holy Land (Priest A); Berserker's War March moves row 4 -> 5 so the Banner path still opens row 6 alone
       NEW       Oath of Legions (Warrior B), Shatterpoint (Spellblade B), Raincaller (Archer A), Storm of Fists (Monk A), Supernova (Mage A),
                 Saint's Covenant (Priest B), Shroud of Night (Assassin A), Death Sentence (Assassin B) - SkyyClasses 0.1.50 applies them
                 (sold only while tree:reads:SkyyClasses lists their Class.fx.<code>; an older SkyyClasses shows them as coming soon)
     A path capstone is a node of its path: buying it takes that path (the other path's capstone locks like the rest of that path). Each
     path alone opens row 6 (rows 1-5 >= 25 ranks with the trunk, row 5 >= 3 - asserted).
  2. THE ASSASSIN'S SECOND A1-ALT SHADOW MARK (SkyyClasses 0.1.50, tier 4): the Assassin's branch 1 splits like every other class's - path A
     Vanishing Act (unchanged), path B Shadow Mark (its 4 modifier unlock nodes + Lingering Mark, Quiet Mark, Killing Intent; the alt at row
     5). The Assassin's tree now has two paths that lock each other (TreeV3.CPB); every old node keeps its key and its row.
  3. THE ONE-TIME alt063 UPDATE (unchanged machinery) for an Assassin file not updated since 0.6.2: SkyyClasses' stored pick predates Shadow
     Mark (an Assassin could never use "B"), so for the Assassin tree the pick is ignored and the path its ranks show is kept (Vanishing Act on
     a tie - TreeV3.NOPICK064); every other class follows the pick as in 0.6.3.
  ICONS: art/r064-icons (tools/art/make_r064_icons.py; its own manifest, sha256 + bytes checked): 11 node icons + the Shadow Mark picture
  (the row-5 ability node Skyy_NodeIcon_Assassin_B1R5Free).
  SAVED DATA: none - no migration (new nodes start at 0 ranks; moved nodes keep their ranks by key; an Assassin who kept Vanishing Act from
  the 0.6.3 update (Class.Assassin.gf A4a) is on the Vanishing Act path - Shadow Mark needs a class-tree respec, like every other class
  since 0.6.3). ROLLBACK to 0.6.3: together with SkyyClasses 0.1.49; ranks on the new nodes are dropped by 0.6.3's first save of that file
  (its writer knows only its own nodes) and their points come back as free points - re-buy them after rolling forward; the moved
  capstones go back to row 5 (keys + ranks kept).
'''

P = G.Patch(os.path.join(ROOT, "SkyyTrees", "build_skyytrees_0.6.3.py"), os.path.join(ROOT, "SkyyTrees", "build_skyytrees_0.6.4.py"))
if "--out" in sys.argv:
    P.dst = os.path.abspath(sys.argv[sys.argv.index("--out") + 1])
assert P.has('VERSION = "0.6.3"') and P.has("0.6.3 (2026-10-24) = SAPLINGS FROM LEAVES") and not P.has("0.6.4 (2026-10-24)"), "not the generated SkyyTrees 0.6.3 script"
REG0, SYS0, CLS0 = P.s.count("registerCommand("), P.s.count("registerSystem("), P.s.count("makeClass(")

P.rep('''"""SkyyTrees 0.6.3 - build script (javassist via jpype, tools/skyybuild.py). Owner: Skyy (they/them).
GENERATED by tools/trees_0_6_3_patch.py from build_skyytrees_0.6.2.py (the SET pin) - edit the patch, not this file.
''', '''"""SkyyTrees 0.6.4 - build script (javassist via jpype, tools/skyybuild.py). Owner: Skyy (they/them).
GENERATED by tools/trees_0_6_4_patch.py from build_skyytrees_0.6.3.py (the SET pin) - edit the patch, not this file.
''' + NOTE + '''
SkyyTrees 0.6.3 - GENERATED by tools/trees_0_6_3_patch.py from build_skyytrees_0.6.2.py:
''')
P.rep('VERSION = "0.6.3"', 'VERSION = "0.6.4"')

# ======================================================================================================== 1 + 2. the layout (data)
P.rep('''V3D.r063_apply()             # 0.6.3: branch 1 splits into the two A1-alt paths (the alts at row 5) - AFTER v4_apply
''', '''V3D.r064_apply()             # 0.6.3: branch 1 splits into the two A1-alt paths (the alts at row 5) - AFTER v4_apply; 0.6.4: r064_apply = Shadow Mark (the
                             # Assassin's A4b) + r063's split + a capstone at the end of every path (it runs r063_apply itself)
assert V3D.R063_APPLIED and V3D.R064_APPLIED
print("0.6.4 per-path capstones: %s" % "; ".join("%s %s" % (_cn, ", ".join("%s %s->%s" % (_m[1], _m[2] or "new", _m[3]) for _m in V3D.R064_MOVES[_cn]))
                                                for _cn in sorted(V3D.R063_SPLIT) if V3D.R064_MOVES.get(_cn)))
''')
# the Assassin's ability table (the build cross-checks it against the newest SkyyClasses build script: 0.1.50 adds Shadow Mark)
P.rep(''"('VanishingAct', 'Vanishing Act', ['Radius', 'Duration', 'Slow', 'Efficiency']), None], 'Warrior':",
      ''"('VanishingAct', 'Vanishing Act', ['Radius', 'Duration', 'Slow', 'Efficiency']), ('ShadowMark', 'Shadow Mark', ['Duration', 'Power', 'Radius', 'Efficiency'])], 'Warrior':")
P.rep('''C_NOUNS = ['First Strike damage', ''', '''C_NOUNS = ['Exposed bonus', 'First Strike damage', ''')   # 0.6.4: Shadow Mark's level-gain noun (SkyyClasses 0.1.50 AB_NOUN)

# the 0.3 ability-node table (kept for old files): the Assassin's A4b column is a real ability now - no hidden ability node is left
P.rep('''assert _HIDM == [("Assassin", "A4b")], _HIDM   # 0.3.18: no modifier slots - the Assassin's missing A1-alt B is the only hidden ability node
''', '''assert _HIDM == [], _HIDM   # 0.3.18: no modifier slots - the Assassin's missing A1-alt B was the only hidden ability node; 0.6.4: Shadow Mark fills it
''')

# the one-time alt063 update (a file not updated since 0.6.2): the Assassin had ONE A1-alt there - SkyyClasses' stored pick says nothing
# about Shadow Mark (an old "B" was never usable by an Assassin), so for the Assassin tree the path its ranks show is kept (Vanishing Act on
# a tie) and the pick is ignored; every other class as in 0.6.3
P.rep('''           "public static final boolean[] CPB = %s;" % jbool(["A4b" in V3D.CLASS_LINES[_cn] for _cn in CLASSES]),
''', '''           "public static final boolean[] CPB = %s;" % jbool(["A4b" in V3D.CLASS_LINES[_cn] for _cn in CLASSES]),
           "public static final boolean[] NOPICK064 = %s;" % jbool([_cn == V3D.R064_ALT[0] for _cn in CLASSES]),   # 0.6.4: the class whose A4b is new (the Assassin)
''')
P.rep('''      int byPick = !usePick ? 0 : ("B".equalsIgnoreCase(pick) ? 2 : ("A".equalsIgnoreCase(pick) ? 1 : 0));
''', '''      int byPick = !usePick || @PKG@.TreeV3.NOPICK064[ci] ? 0 : ("B".equalsIgnoreCase(pick) ? 2 : ("A".equalsIgnoreCase(pick) ? 1 : 0));   // 0.6.4: not for the Assassin (its pick predates Shadow Mark)
''')

# ======================================================================================================== 3. the icons (art/r064-icons)
P.rep('''for _iid, _v in R062_ICONS.items():
    assert _iid not in NI_ITEMS and _v[0] != NI_ITEMS["Skyy_NodeIcon_Beastmastery_B3R1b"][0]
    NI_ITEMS[_iid] = (_ni_png(_v[0], _iid), _v[1], _v[2])
''', '''for _iid, _v in R062_ICONS.items():
    assert _iid not in NI_ITEMS and _v[0] != NI_ITEMS["Skyy_NodeIcon_Beastmastery_B3R1b"][0]
    NI_ITEMS[_iid] = (_ni_png(_v[0], _iid), _v[1], _v[2])
# 0.6.4: the cap064 icons (art/r064-icons, tools/art/make_r064_icons.py - its own manifest, sha256 + bytes checked; the shared class manifest
# is counted by the 0.6.3 build): the 8 new path capstones + the 3 Shadow Mark passives, and the Shadow Mark ability picture as the
# Assassin's row-5 ability node (B1R5Free, the free2 of the Assassin's OR pair)
_R64_DIR = os.path.join(_NI_ROOT, "art", "r064-icons")
_R64_MAN = json.load(open(os.path.join(_R64_DIR, "manifest.json"), encoding="utf8"))
_R64_SHA = dict((_f["path"], (_f["sha256"], _f["bytes"])) for _f in _R64_MAN["files"])


def _r64_png(p):
    _d = open(os.path.join(_R64_DIR, *p.split("/")), "rb").read()
    assert p in _R64_SHA and _ni_hl.sha256(_d).hexdigest() == _R64_SHA[p][0] and len(_d) == _R64_SHA[p][1], "0.6.4: %s is not the r064 manifest's file" % p
    return _ni_png(_d, p)


R064_NI = {}
for _n in _R64_MAN["nodes"]:
    assert _n["file"] == "Common/Icons/ItemsGenerated/%s.png" % _n["icon_id"]
    R064_NI[_n["icon_id"]] = (_r64_png(_n["file"]), _n["name"], _n["key"])
R064_NI["Skyy_NodeIcon_Assassin_B1R5Free"] = (_r64_png(_R64_MAN["ability"]["file"]), "Shadow Mark", "Assassin.b1.r5.free")
assert sorted(_n["key"] for _n in _R64_MAN["nodes"]) == sorted([_c[3] for _c in V3D.R064_CAPS] + [_p["ikey"] for _p in V3D.R064_PASSIVES]), "0.6.4: one icon per new node"
for _iid, _v in sorted(R064_NI.items()):
    assert _iid not in NI_ITEMS, _iid
    NI_ITEMS[_iid] = _v
''')
P.rep('''assert (_NI_SK, len(NI_ITEMS) - _NI_SK - _NI_AB, _NI_AB) == (361 + 2, 283, 40)   # 0.6.2: + the two Beastmastery hatching icons
''', '''assert (_NI_SK, len(NI_ITEMS) - _NI_SK - _NI_AB, _NI_AB) == (361 + 2, 283 + 11, 40 + 1)   # 0.6.2: + the two Beastmastery hatching icons; 0.6.4: + the 11 cap064 node icons + Shadow Mark's row-5 node
''')

assert P.s.count("registerCommand(") == REG0 and P.s.count("registerSystem(") == SYS0 and P.s.count("makeClass(") == CLS0, "0.6.4: no class / command / system"
P.finish()
print("wrote", P.dst)
